    if not intervals:
        return []

    # Sort intervals by start time
    intervals.sort(key=lambda x: x[0])

    merged = [intervals[0]]

    for interval in intervals[1:]:
        last_merged = merged[-1]
        # If the current interval overlaps or touches the last merged interval
        if interval[0] <= last_merged[1]:
            # Merge them by updating the end of the last merged interval
            last_merged[1] = max(last_merged[1], interval[1])
        else:
            # No overlap, add the current interval as a new merged interval
            merged.append(interval)

    return merged

def edit_distance(a: str, b: str) -> int:
    m, n = len(a), len(b)

    # Create a DP table
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Base cases
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(
                    dp[i - 1][j],      # deletion
                    dp[i][j - 1],      # insertion
                    dp[i - 1][j - 1]   # substitution
                )

    return dp[m][n]

