def evaluate(expr: str) -> float:
    """
    Evaluates an arithmetic expression string supporting + - * / parentheses,
    unary minus, integers and decimals, with correct precedence.

    Raises ValueError on malformed input.
    """
    if not expr or not expr.strip():
        raise ValueError("Empty expression")

    # Tokenize the expression
    tokens = tokenize(expr)

    # Parse and evaluate using recursive descent parser
    parser = Parser(tokens)
    result = parser.parse_expression()

    if parser.pos < len(parser.tokens):
        raise ValueError(f"Unexpected token: {parser.tokens[parser.pos]}")

    return result


def tokenize(expr: str):
    """
    Tokenize the expression into numbers, operators, and parentheses.
    """
    tokens = []
    i = 0
    s = expr.strip()

    while i < len(s):
        c = s[i]

        if c.isspace():
            i += 1
            continue

        if c in '+-*/()':
            tokens.append(c)
            i += 1
            continue

        if c.isdigit() or c == '.':
            # Parse a number (integer or decimal)
            j = i
            has_dot = False
            while j < len(s) and (s[j].isdigit() or s[j] == '.'):
                if s[j] == '.':
                    if has_dot:
                        raise ValueError(f"Invalid number at position {i}")
                    has_dot = True
                j += 1

            num_str = s[i:j]
            if num_str == '.':
                raise ValueError(f"Invalid number at position {i}")
            if num_str.startswith('.'):
                num_str = '0' + num_str
            if num_str.endswith('.'):
                # Trailing dot is okay, it's a valid decimal
                pass
            try:
                num = float(num_str)
            except ValueError:
                raise ValueError(f"Invalid number: {num_str}")
            tokens.append(num)
            i = j
            continue

        raise ValueError(f"Unexpected character: {c} at position {i}")

    return tokens


class Parser:
    """
    Recursive descent parser for arithmetic expressions.

    Grammar:
    expression := term (('+' | '-') term)*
    term := factor (('*' | '/') factor)*
    factor := ('-' | '+') factor | primary
    primary := NUMBER | '(' expression ')'
    """

    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def current_token(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self, expected=None):
        token = self.current_token()
        if token is None:
            raise ValueError(f"Unexpected end of input, expected {expected}")
        if expected is not None and token != expected:
            raise ValueError(f"Expected {expected}, got {token}")
        self.pos += 1
        return token

    def parse_expression(self):
        """Parse addition and subtraction (lowest precedence)."""
        left = self.parse_term()

        while self.current_token() in ('+', '-'):
            op = self.consume()
            right = self.parse_term()
            if op == '+':
                left = left + right
            else:
                left = left - right

        return left

    def parse_term(self):
        """Parse multiplication and division (higher precedence)."""
        left = self.parse_factor()

        while self.current_token() in ('*', '/'):
            op = self.consume()
            right = self.parse_factor()
            if op == '*':
                left = left * right
            else:
                if right == 0:
                    raise ValueError("Division by zero")
                left = left / right

        return left

    def parse_factor(self):
        """Parse unary plus/minus and primary expressions."""
        token = self.current_token()

        if token == '-':
            self.consume()
            operand = self.parse_factor()
            return -operand

        if token == '+':
            self.consume()
            operand = self.parse_factor()
            return operand

        return self.parse_primary()

    def parse_primary(self):
        """Parse numbers and parenthesized expressions."""
        token = self.current_token()

        if token is None:
            raise ValueError("Unexpected end of input")

        if isinstance(token, (int, float)):
            self.consume()
            return float(token)

        if token == '(':
            self.consume()
            result = self.parse_expression()
            if self.current_token() != ')':
                raise ValueError("Missing closing parenthesis")
            self.consume()
            return result

        if token == ')':
            raise ValueError("Unexpected closing parenthesis")

        raise ValueError(f"Unexpected token: {token}")

